use tcpe_java_network::network::{resource_packs::PackRequest,resource_pack_download::download_fonts};
#[tokio::main] async fn main(){let path=std::env::args().nth(1).expect("private request JSON path");let requests:Vec<PackRequest>=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let result=download_fonts(requests.into_iter().next().unwrap(),1,3).await.expect("download and decode pack");println!("{}",serde_json::json!({"connection":result.connection,"generation":result.generation,"font_count":result.fonts.len(),"texture_count":result.textures.len(),"glyph_count":result.fonts.iter().map(|f|f.glyphs.len()).sum::<usize>()}));}
